const fs = require("fs");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
(async () => {
  const tw = require("tailwindcss");
  const dir = "/w/node_modules/tailwindcss";
  const css = fs.readFileSync(dir + "/index.css", "utf8");
  const ds = await tw.__unstable__loadDesignSystem(css, { base: dir });
  const opts = { collapse: true, logicalToPhysical: true, rem: 16 };
  const ctl = ds.canonicalizeCandidates(["mt-1", "mb-1"], opts);
  if (ctl.join(" ") !== "my-1") broken("control mt-1 mb-1 gave " + ctl.join(" "));
  const got = ds.canonicalizeCandidates(["border-t-red-500", "border-b-red-500"], opts);
  if (got.join(" ") === "border-y-red-500") { console.log("OK: border-t-red-500 border-b-red-500 canonicalizes to border-y-red-500"); return; }
  if (got.includes("border-t-red-500") && got.includes("border-b-red-500")) symptom("border-t-red-500 border-b-red-500 is not collapsed into border-y-red-500");
  broken("border-t-red-500 border-b-red-500 gave " + got.join(" "));
})().catch(e => broken(String((e && e.stack) || e)));

